import AppKit

/// Watches the general pasteboard for new copies. macOS has no change notification, so it polls
/// `changeCount` (cheap) twice a second, like every clipboard manager.
@MainActor
public final class PasteboardWatcher {
  public struct Copy: Sendable {
    /// Plain text of the copy, if it has any.
    public var text: String?
    /// Marked concealed/transient/auto-generated by the app that wrote it (password managers do).
    public var isConcealed: Bool
    /// Frontmost app when the copy was noticed.
    public var sourceApp: String?
  }

  /// Types apps use to say "don't record this" (nspasteboard.org) plus older vendor conventions.
  public static let concealedTypes: Set<String> = [
    "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType", "org.nspasteboard.AutoGeneratedType",
    "com.agilebits.onepassword", "de.petermaurer.TransientPasteboardType", "com.typeit4me.clipping",
    "Pasteboard generator type",
  ]
  public static let transientType = NSPasteboard.PasteboardType("org.nspasteboard.TransientType")

  public var onCopy: ((Copy) -> Void)?
  private var timer: Timer?
  private var lastChangeCount = NSPasteboard.general.changeCount

  public init() {}

  public func start() {
    guard timer == nil else { return }
    lastChangeCount = NSPasteboard.general.changeCount
    timer = Timer.scheduledTimer(withTimeInterval: 0.5, repeats: true) { [weak self] _ in
      MainActor.assumeIsolated { self?.poll() }
    }
  }

  public func stop() {
    timer?.invalidate()
    timer = nil
  }

  /// Puts `text` on the clipboard as the user's own copy (it will be picked up as a new copy).
  public static func write(_ text: String) {
    let pasteboard = NSPasteboard.general
    pasteboard.clearContents()
    pasteboard.setString(text, forType: .string)
  }

  private func poll() {
    let pasteboard = NSPasteboard.general
    guard pasteboard.changeCount != lastChangeCount else { return }
    lastChangeCount = pasteboard.changeCount
    let types = Set((pasteboard.types ?? []).map(\.rawValue))
    onCopy?(
      Copy(
        text: pasteboard.string(forType: .string), isConcealed: !types.isDisjoint(with: Self.concealedTypes),
        sourceApp: NSWorkspace.shared.frontmostApplication?.bundleIdentifier))
  }
}
